/* Centro I.A. — interfaz conectada a servidor. No guarda contraseñas ni tokens en el navegador. */
const $ = selector => document.querySelector(selector);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = x => {if(!x)return '—';const d=new Date(`${x.slice(0,10)}T12:00:00`);return Number.isNaN(+d)?esc(x):new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric'}).format(d);};
const fmtStamp = x => x?`${fmtDate(x)} · ${String(x).slice(11,16)} UTC`:'—';
const money = cents => new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format((cents||0)/100);
const attr = v => esc(v);
const statusLabel = status => ({confirmed:'Confirmada',cancelled:'Cancelada',attended:'Asistió',no_show:'No asistió',published:'Publicado',draft:'Borrador'}[status]||status);
const statusTag = s => `<span class="tag ${s==='confirmed'||s==='published'?'green':s==='cancelled'||s==='no_show'?'red':'gold'}">${esc(statusLabel(s))}</span>`;
const empty = (message,action='')=>`<div class="empty">${esc(message)}${action?`<div style="margin-top:12px">${action}</div>`:''}</div>`;
const page = (label,title,subtitle,button='')=>`<header class="page-heading"><div><span class="eyebrow">${esc(label)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${button}</header>`;
const kpi = (title,value,tip='')=>`<article class="kpi"><small>${esc(title)}</small><strong>${esc(value)}</strong><div class="hint">${esc(tip)}</div></article>`;
const badge = (text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const app = {user:null,csrf:'',businesses:[],businessId:null,mode:'user',view:'discover',data:{},days:30,authView:'login',aiAnswer:'',creatingBusiness:false,visitCode:null,busy:false,loading:false};
let toaster;
const toast=(msg,error=false)=>{const el=$('#toast');el.textContent=msg;el.className=`toast show ${error?'error':''}`;clearTimeout(toaster);toaster=setTimeout(()=>el.classList.remove('show'),4500);};
async function api(path,{method='GET',body=null}={}){
  const headers={'Accept':'application/json'};if(body!==null)headers['Content-Type']='application/json';if(method!=='GET'&&app.csrf)headers['X-CSRF-Token']=app.csrf;
  let res;
  try{res=await fetch(path,{method,headers,body:body===null?undefined:JSON.stringify(body),credentials:'same-origin'});}catch{throw Error('No se pudo conectar con el servidor. Comprueba que esté iniciado.');}
  let data;try{data=await res.json();}catch{throw Error('El servidor devolvió una respuesta inesperada.');}
  if(!res.ok)throw Error(data.error||`Error HTTP ${res.status}`);
  return data;
}
async function boot(){try{const data=await api('/api/bootstrap');app.user=data.user;app.csrf=data.csrf||'';app.businesses=data.businesses||[];app.businessId=app.businesses[0]?.id||null;app.mode=app.user?.accountType==='company'&&app.businessId?'business':'user';app.view=app.mode==='business'?'dashboard':'discover';await refresh();}catch(e){$('#app').innerHTML=`<main class="loading-screen"><h2>No se puede iniciar Centro I.A.</h2><p>${esc(e.message)}</p><button class="btn btn-primary" data-action="retry">Reintentar</button></main>`;}}
async function refresh(){if(!app.user){render();return;}if(app.mode==='business'&&!app.businessId){render();return;}app.loading=true;render();try{await loadData();}catch(e){app.data={error:e.message};}finally{app.loading=false;render();}}
async function go(view){app.view=view;window.scrollTo({top:0,behavior:'instant'});await refresh();}
const bid=()=>encodeURIComponent(app.businessId);
async function loadData(){const b=bid();const get=(u)=>api(u);let data={};if(app.mode==='business'){
  switch(app.view){
    case'dashboard':{const [overview,reservations,events]=await Promise.all([get(`/api/businesses/${b}/overview?days=30`),get(`/api/businesses/${b}/reservations`),get(`/api/events?businessId=${b}&all=1`)]);data={overview,reservations:reservations.slice(0,5),events:events.slice(0,5)};break;}
    case'analytics':data={overview:await get(`/api/businesses/${b}/overview?days=${app.days}`)};break;
    case'customers':data={customers:await get(`/api/businesses/${b}/customers`)};break;
    case'visits':{const [customers,locations,visits]=await Promise.all([get(`/api/businesses/${b}/customers`),get(`/api/businesses/${b}/locations`),get(`/api/businesses/${b}/visits`)]);data={customers,locations,visits};break;}
    case'events':{const [events,locations]=await Promise.all([get(`/api/events?businessId=${b}&all=1`),get(`/api/businesses/${b}/locations`)]);data={events,locations};break;}
    case'reservations':data={reservations:await get(`/api/businesses/${b}/reservations`)};break;
    case'rewards':{const [rewards,redemptions]=await Promise.all([get(`/api/businesses/${b}/rewards`),get(`/api/businesses/${b}/redemptions`)]);data={rewards,redemptions};break;}
    case'campaigns':data={campaigns:await get(`/api/businesses/${b}/campaigns`)};break;
    case'insights':data={insights:await get(`/api/businesses/${b}/insights`)};break;
    case'team':data={team:await get(`/api/businesses/${b}/team`)};break;
    case'settings':data={business:await get(`/api/businesses/${b}`),locations:await get(`/api/businesses/${b}/locations`)};break;
    case'audit':data={audit:await get(`/api/businesses/${b}/audit`)};break;
  }
}else{
  switch(app.view){
    case'discover':data={businesses:await get('/api/businesses')};break;
    case'events':{const [events,reservations]=await Promise.all([get('/api/events'),get('/api/me/reservations')]);data={events,reservations};break;}
    case'reservations':data={reservations:await get('/api/me/reservations')};break;
    case'wallet':{const [wallet,ledger]=await Promise.all([get('/api/me/wallet'),get('/api/me/ledger')]);const prizes=await Promise.all(wallet.map(w=>get(`/api/businesses/${encodeURIComponent(w.business_id)}/rewards`)));data={wallet:wallet.map((w,i)=>({...w,rewards:prizes[i]})),ledger};break;}
    case'notifications':data={notifications:await get('/api/me/notifications')};break;
    case'profile':data={};break;
  }
}
app.data=data;
}
function render(){
  if(!app.user){$('#app').innerHTML=renderAccess();return;}
  if(app.user.accountType==='company'&&(!app.businessId||app.creatingBusiness)){$('#app').innerHTML=renderCreateBusiness();return;}
  $('#app').innerHTML=renderShell();
}
function renderAccess(){let reg=app.authView==='register';return `<div class="access"><section class="access-brand-panel"><div class="access-brand"><div class="brand-mark">✦</div><div><strong style="font-size:1.35rem;font-weight:900;letter-spacing:-.05em">Centro I.A.</strong><div class="eyebrow" style="font-size:.62rem;letter-spacing:.09em">Un motivo para volver</div></div></div><h1 class="access-title">Conecta.<br><em>Descubre.</em><br>Vuelve.</h1><p class="access-intro">Un espacio para negocios que quieren crecer y personas que disfrutan descubrir lugares y acumular beneficios reales.</p><div class="access-benefits"><p><span>✓</span> Reservaciones conectadas</p><p><span>✓</span> Puntos y recompensas</p><p><span>✓</span> Estadísticas verificables</p><p><span>✓</span> Datos en el servidor</p></div><p class="helper" style="text-align:left;margin-top:27px">¿Quieres comparar el diseño anterior? <a href="/demo/">Abrir demo original</a></p></section><section class="access-card"><span class="eyebrow">CUENTAS EN SERVIDOR</span><h2 style="margin-top:9px">${reg?'Crea tu cuenta':'Bienvenido de nuevo'}</h2><p>${reg?'Elige si crearás un negocio o si usarás la plataforma como cliente.':'Inicia sesión para acceder a tus datos y tus reservas.'}</p><form data-form="${reg?'register':'login'}">${reg?`<label>Nombre completo<input name="name" autocomplete="name" required minlength="2" maxlength="90" placeholder="Tu nombre"></label><fieldset style="padding:0;border:0"><legend style="font-size:.83rem;color:#52697e;font-weight:700;margin-bottom:8px">Tipo de cuenta</legend><div class="account-choice"><label><input type="radio" name="accountType" value="user" checked><span><strong>👤 Usuario</strong><small>Descubrir y reservar</small></span></label><label><input type="radio" name="accountType" value="company"><span><strong>🏪 Empresa</strong><small>Gestionar negocios</small></span></label></div></fieldset>`:''}<label>Correo electrónico<input type="email" name="email" autocomplete="email" placeholder="correo@ejemplo.com" maxlength="255" required></label><label>Contraseña<input type="password" name="password" autocomplete="${reg?'new-password':'current-password'}" minlength="${reg?'10':'1'}" maxlength="128" required placeholder="${reg?'Mínimo 10 caracteres':'Tu contraseña'}"></label>${reg?`<small>Usa una contraseña exclusiva. Para publicar comercialmente falta verificar correos y configurar un proveedor de autenticación.</small>`:''}<button class="btn btn-primary" type="submit">${reg?'Crear cuenta':'Iniciar sesión'} ↗</button></form><footer><button type="button" class="btn btn-link" data-action="auth-toggle">${reg?'¿Ya tienes cuenta? Inicia sesión':'¿No tienes cuenta? Regístrate'}</button><small>Aplicación local conectada • No introduzcas datos sensibles para pruebas</small></footer></section></div>`;}
function renderCreateBusiness(){return `<div class="access"><section class="access-brand-panel"><div class="access-brand"><div class="brand-mark">✦</div><strong style="font-size:1.35rem">Centro I.A.</strong></div><h1 class="access-title">Dale vida a <em>tu negocio.</em></h1><p class="access-intro">Completa los datos iniciales y podrás publicar eventos, sumar clientes, gestionar recompensas y consultar estadísticas reales.</p><div class="access-benefits"><p><span>1</span> Crea tu negocio</p><p><span>2</span> Publica eventos o recompensas</p><p><span>3</span> Invita clientes reales</p></div><p style="margin-top:24px"><button class="btn btn-soft" data-action="logout">Cerrar sesión</button></p></section><section class="access-card"><span class="eyebrow">CONFIGURACIÓN INICIAL</span><h2 style="margin-top:8px">Crear empresa</h2><p>Comienza con los datos esenciales. Puedes editarlos después.</p><form data-form="create-business"><label>Nombre del negocio<input name="name" required minlength="2" maxlength="100" placeholder="Ej. Café Bahía"></label><label>Categoría<select name="category"><option>Cafetería</option><option>Restaurante</option><option>Belleza</option><option>Bienestar</option><option>Arte y talleres</option><option>Comercio</option><option>Otro</option></select></label><label>Ciudad<input name="city" maxlength="80" placeholder="Ensenada, Baja California"></label><label>Dirección<input name="address" maxlength="180" placeholder="Calle, número y colonia"></label><label>Descripción<textarea name="description" maxlength="500" placeholder="Cuéntanos qué hace especial a tu negocio"></textarea></label><button class="btn btn-primary" type="submit">Crear negocio y comenzar ↗</button></form><div class="divider"></div><h3>¿Te invitaron a un negocio?</h3><p>Si recibiste una invitación, puedes unirte directamente sin crear una empresa nueva.</p><form data-form="accept-invite" class="vstack" style="margin-top:12px"><label>Código de invitación<input name="code" required placeholder="Pega tu código personal"></label><button class="btn btn-soft" type="submit">Aceptar invitación y entrar al equipo</button></form>${app.creatingBusiness&&app.businessId?`<button class="btn btn-link" data-action="cancel-new-business" style="margin-top:14px">Volver al panel de mi empresa</button>`:''}</section></div>`;}
const businessNav=[['dashboard','⌂','Inicio'],['analytics','▥','Estadísticas'],['customers','♧','Clientes'],['visits','✚','Registrar visitas'],['events','▦','Eventos'],['reservations','◷','Reservaciones'],['rewards','♛','Recompensas'],['campaigns','✉','Campañas'],['insights','✧','Centro I.A.'],['team','♙','Equipo'],['settings','⚙','Configuración'],['audit','▤','Auditoría']];
const userNav=[['discover','⌂','Descubrir'],['events','▦','Eventos'],['reservations','◷','Mis reservas'],['wallet','♛','Mi billetera'],['notifications','♧','Avisos'],['profile','⚙','Mi perfil']];
function renderShell(){const b=app.businesses.find(x=>x.id===app.businessId);const owner=app.user.accountType==='company';const nav=app.mode==='business'?businessNav:userNav;const current=nav.find(n=>n[0]===app.view)?.[2]||'Inicio';const n=b?.name||'Mi negocio';return `<div class="shell"><aside class="sidebar"><div class="sidebar-header"><div class="brand-mark">✦</div><div><strong>Centro I.A.</strong><small>UN MOTIVO PARA VOLVER</small></div></div><p class="sidebar-label">${app.mode==='business'?'GESTIÓN DE NEGOCIO':'EXPERIENCIA DE CLIENTE'}</p><nav class="navlinks" aria-label="Secciones">${nav.map(([id,icon,title])=>`<button type="button" class="${app.view===id?'active':''}" data-nav="${id}" aria-current="${app.view===id?'page':'false'}"><span class="navicon">${icon}</span>${title}</button>`).join('')}</nav><div class="sidebar-note"><strong>${app.mode==='business'?'Tu negocio, con datos reales':'Tu comunidad te espera'}</strong>${app.mode==='business'?'Cada reserva, visita y canje queda registrado en el servidor.':'Descubre lugares, confirma tus planes y guarda tus beneficios.'}</div><div class="sidebar-foot"><a href="/demo/">↗ Ver demo anterior</a><button class="btn btn-link" data-action="logout">Salir de mi cuenta</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">✦ &nbsp;Centro I.A. &nbsp;/&nbsp; <strong>${esc(current)}</strong></div><div class="top-actions">${owner&&app.mode==='business'&&app.businesses.length>1?`<select class="business-select" id="business-select" aria-label="Seleccionar negocio">${app.businesses.map(x=>`<option value="${attr(x.id)}" ${x.id===app.businessId?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}${owner&&app.mode==='business'?`<button class="btn btn-soft btn-sm" data-action="new-business">＋ Negocio</button>`:''}${owner?`<button class="btn btn-soft btn-sm" data-action="switch-mode">${app.mode==='business'?'Vista usuario':'Panel negocio'}</button>`:''}<div class="user-bubble" title="${attr(app.user.name)}">${esc(app.user.name.trim().slice(0,1).toUpperCase())}</div><button class="btn btn-soft btn-sm" data-action="logout" title="Cerrar sesión">Salir</button></div></header><main class="content" id="maincontent" aria-busy="${app.loading}">${app.loading?`<div class="panel panel-white"><div class="spinner"></div><p style="text-align:center">Consultando información del servidor...</p></div>`:app.data.error?`<div class="error-state">${esc(app.data.error)} <button class="btn btn-sm" data-action="retry">Reintentar</button></div>`:renderView()}</main></div></div>`;}
function renderView(){if(app.mode==='user')switch(app.view){case'discover':return discoverPage();case'events':return userEventsPage();case'reservations':return userReservationsPage();case'wallet':return walletPage();case'notifications':return notificationsPage();case'profile':return profilePage();default:return discoverPage();}switch(app.view){case'dashboard':return dashboardPage();case'analytics':return analyticsPage();case'customers':return customersPage();case'visits':return visitsPage();case'events':return companyEventsPage();case'reservations':return companyReservationsPage();case'rewards':return rewardsPage();case'campaigns':return campaignsPage();case'insights':return insightsPage();case'team':return teamPage();case'settings':return settingsPage();case'audit':return auditPage();default:return dashboardPage();}}
function chartHTML(series){const max=Math.max(1,...series.map(x=>x.visits));return `<div class="chart" role="img" aria-label="Gráfica de visitas por día; ${series.reduce((n,x)=>n+x.visits,0)} visitas en el periodo">${series.map(x=>`<div class="bar" title="${attr(x.date)}: ${x.visits} visitas" style="height:${Math.max(2,x.visits/max*100)}%"></div>`).join('')}</div><div class="chart-foot"><span>${fmtDate(series[0]?.date)}</span><span>${fmtDate(series.at(-1)?.date)}</span></div>`;}
function dashboardPage(){const {overview:o,reservations:r,events}=app.data;const s=o.stats;return `${page('TU NEGOCIO EN CENTRO I.A.','¡Hola, '+app.user.name.split(' ')[0]+'! ✨','Indicadores registrados en el servidor, sin cifras de ejemplo.',`<button class="btn btn-primary" data-nav="visits">＋ Registrar visita</button>`)}<section class="grid four">${kpi('Clientes vinculados',s.members,'Cuentas reales')}${kpi('Visitas · últimos 30 días',s.visits,'Registros verificados')}${kpi('Reservas activas',s.reservations,'Creadas en el periodo')}${kpi('Canjes realizados',s.redemptions,'Últimos 30 días')}</section><section class="grid dashboard-layout"><article class="panel panel-dark hero"><div><div class="eyebrow">✦ TU CLUB ESTÁ ACTIVO</div><h2>Haz que tus clientes tengan más motivos para volver.</h2><p>Publica experiencias, registra visitas, ofrece recompensas y mide el crecimiento con información real.</p></div><div class="hero-bottom"><div>${badge('Sin datos inventados','gold')} ${badge('Multiusuario')}</div><button class="btn btn-primary" data-nav="events">Publicar evento ↗</button></div></article><article class="panel"><div class="panel-head"><div><h3>Reservas recientes</h3><p>Últimas operaciones registradas</p></div><button class="inline-link" data-nav="reservations">Ver todas →</button></div>${r.length?`<div class="mini-list">${r.map(x=>`<div class="item"><div><strong>${esc(x.customer_name)}</strong><p>${esc(x.title)} · ${fmtDate(x.date)}</p></div>${statusTag(x.status)}</div>`).join('')}</div>`:empty('Aún no hay reservaciones.')}</article></section><section class="grid two"><article class="panel"><div class="panel-head"><div><h3>Actividad de visitas</h3><p>Últimos 30 días</p></div><button class="inline-link" data-nav="analytics">Análisis →</button></div>${chartHTML(o.series)}<p class="stat-note">Puntos otorgados: ${s.pointsAwarded}. El ingreso no se calcula porque todavía no se procesan cobros.</p></article><article class="panel"><div class="panel-head"><h3>Eventos del negocio</h3><button class="inline-link" data-nav="events">Gestionar →</button></div>${events.length?`<div class="mini-list">${events.map(ev=>`<div class="item"><div><strong>${esc(ev.title)}</strong><p>${fmtDate(ev.date)} · ${esc(ev.time)}</p></div>${statusTag(ev.status)}</div>`).join('')}</div>`:empty('Crea tu primer evento para comenzar.')}</article></section>`;}
function analyticsPage(){let o=app.data.overview,s=o.stats;return `${page('INTELIGENCIA DE NEGOCIO','Estadísticas reales','Todos los indicadores salen de la base de datos, no de cifras predefinidas.',`<div class="gap8"><button class="btn ${app.days===7?'btn-primary':'btn-soft'} btn-sm" data-days="7">7 días</button><button class="btn ${app.days===30?'btn-primary':'btn-soft'} btn-sm" data-days="30">30 días</button><button class="btn ${app.days===90?'btn-primary':'btn-soft'} btn-sm" data-days="90">90 días</button><a class="btn btn-soft btn-sm" href="/api/businesses/${bid()}/export.csv">Exportar clientes CSV ↧</a></div>`)}<div class="grid four">${kpi('Miembros',s.members,'Clientes vinculados')}${kpi('Visitas',s.visits,`${o.days} días`)}${kpi('Puntos otorgados',s.pointsAwarded,`${o.days} días`)}${kpi('Reservaciones',s.reservations,`${o.days} días`)}</div><div class="grid two"><div class="panel"><div class="panel-head"><h3>Visitas por día</h3>${badge(`${o.days} días`)}</div>${chartHTML(o.series)}</div><div class="panel"><div class="panel-head"><h3>Actividad de fidelidad</h3>${badge('Datos registrados','green')}</div><div class="mini-list"><div class="item"><strong>Canjes</strong><strong>${s.redemptions}</strong></div><div class="item"><strong>Eventos publicados</strong><strong>${s.events}</strong></div><div class="item"><strong>Puntos distribuidos</strong><strong>${s.pointsAwarded}</strong></div><div class="item"><strong>Ingresos por pagos</strong><strong>Sin integrar</strong></div></div></div></div><div class="recommendation"><strong>Sobre la precisión de estos indicadores</strong><p>${esc(o.note)} No se inventan ventas, retención ni conversiones. Las métricas avanzadas necesitarán registros de pagos o transacciones vinculadas.</p></div>`;}
function customersPage(){const cs=app.data.customers;return `${page('PERSONAS QUE VUELVEN','Clientes vinculados','Los clientes aparecen después de registrar su primera visita, con su cuenta propia.',`<button class="btn btn-primary" data-nav="visits">＋ Registrar visita</button>`)}<section class="panel"><div class="panel-head"><h3>Directorio de clientes</h3>${badge(`${cs.length} clientes`)}</div>${cs.length?`<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Visitas</th><th>Puntos</th><th>Última visita</th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.email)}</td><td>${c.visits}</td><td>${c.points}</td><td>${fmtDate(c.last_visit_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay clientes registrados. Invita a alguien a crear una cuenta y registrar una visita.')}</section><p class="help">Solo el personal autorizado del negocio puede ver este directorio. No uses datos de personas sin su consentimiento.</p>`;}
function visitsPage(){const {customers,locations,visits}=app.data;return `${page('FIDELIZACIÓN','Visitas y puntos','Cada visita se registra una sola vez y actualiza la billetera del cliente.')}<section class="panel panel-white"><div class="panel-head"><div><h3>✓ Registrar visita con QR seguro</h3><p>El cliente genera un QR temporal válido durante 5 minutos. Cada código puede usarse una sola vez.</p></div>${badge('Un solo uso','green')}</div><form data-form="checkin" class="vstack"><div class="fields"><label>Código del cliente<input id="qr-code-input" name="code" required maxlength="70" placeholder="CIA-..." autocapitalize="characters"></label><label>Puntos a otorgar<input type="number" name="points" min="0" max="1000" value="10" required></label><label>Sucursal<select name="locationId"><option value="">Sin especificar</option>${locations.map(l=>`<option value="${attr(l.id)}">${esc(l.name)}</option>`).join('')}</select></label><label>Notas<input name="note" maxlength="400" placeholder="Visita confirmada"></label></div><div class="actions"><button type="button" class="btn btn-soft" data-action="scan-qr">▣ Escanear con cámara</button><button class="btn btn-primary" type="submit">Validar QR y sumar puntos</button></div><small>Si el navegador no permite escanear, introduce el código que aparece debajo del QR del cliente.</small></form></section><div class="grid two"><section class="panel"><div class="panel-head"><h3>Registrar visita real</h3>${badge('Servidor','green')}</div><form data-form="visit" class="vstack"><label>Correo de cliente<input name="customerEmail" type="email" list="customer-emails" required placeholder="cliente@correo.com"><datalist id="customer-emails">${customers.map(x=>`<option value="${attr(x.email)}">`).join('')}</datalist></label><div class="fields"><label>Puntos a sumar<input name="points" type="number" min="0" max="1000" value="10" required></label><label>Sucursal<select name="locationId"><option value="">Sin especificar</option>${locations.map(x=>`<option value="${attr(x.id)}">${esc(x.name)}</option>`).join('')}</select></label></div><label>Nota opcional<textarea name="note" maxlength="400" placeholder="Ej. Visita por café y pan"></textarea></label><p class="help">El cliente debe existir como usuario registrado. El servidor verifica puntos y guarda un identificador de operación para prevenir reenvíos accidentales.</p><button class="btn btn-primary" type="submit">✓ Confirmar visita y puntos</button></form></section><section class="panel"><div class="panel-head"><h3>Últimas visitas</h3>${badge(`${visits.length} mostradas`)}</div>${visits.length?`<div class="mini-list">${visits.slice(0,12).map(x=>`<div class="item"><div><strong>${esc(x.name)}</strong><p>${fmtStamp(x.created_at)} · ${esc(x.note||'Sin nota')}</p></div>${badge('+'+x.points+' pts','gold')}</div>`).join('')}</div>`:empty('Las visitas aparecerán aquí al registrarlas.')}</section></div>`;}
function eventCard(event,admin=false,booked=false){let remain=Math.max(0,event.capacity-event.booked),full=remain===0;return `<article class="card"><div class="event-row"><div class="date-tile"><small>${esc(new Intl.DateTimeFormat('es-MX',{month:'short'}).format(new Date(event.date+'T12:00:00')))}</small><strong>${esc(event.date.slice(-2))}</strong></div><div class="copy"><h3>${esc(event.title)}</h3><small>${esc(event.business_name||'')} · ${esc(event.time)} h</small></div></div><p>${esc(event.description||'Una experiencia para tu comunidad.')}</p><div class="gap8">${badge(event.location_name||'Sucursal por definir')}${badge(`${event.booked}/${event.capacity} lugares`)}${admin?statusTag(event.status):badge(event.price_cents?money(event.price_cents):'Entrada gratuita','green')}</div><div class="card-footer"><small>${admin?`${remain} lugares disponibles`:`${remain} cupos libres`}</small>${admin?event.status==='published'?`<button class="btn btn-danger btn-sm" data-action="cancel-event" data-id="${attr(event.id)}">Cancelar evento</button>`:statusTag(event.status):booked?badge('Ya reservaste','green'):`<button class="btn btn-primary btn-sm" data-action="book-event" data-id="${attr(event.id)}" ${full?'disabled':''}>${full?'Sin cupo':'Reservar lugar →'}</button>`}</div></article>`;}
function companyEventsPage(){const {events,locations}=app.data;const futureDate=new Date(Date.now()+86400000).toISOString().slice(0,10);return `${page('EXPERIENCIAS PARA TU COMUNIDAD','Eventos de tu negocio','Publica experiencias reales, define horarios y controla automáticamente los cupos.') }<section class="panel"><div class="panel-head"><h3>Crear evento</h3>${badge('Publicación real','green')}</div><form data-form="event" class="vstack"><div class="fields"><label>Nombre del evento<input name="title" required maxlength="100" placeholder="Tarde de café y música"></label><label>Categoría<input name="category" maxlength="60" placeholder="Café & comunidad"></label><label>Fecha<input name="date" type="date" value="${futureDate}" required></label><label>Hora (horario del negocio)<input name="time" type="time" value="17:30" required></label><label>Cupo máximo<input name="capacity" type="number" min="1" max="100000" value="20" required></label><label>Precio en MXN<input name="price" type="number" step="0.01" min="0" value="0" required></label><label class="full">Sucursal<select name="locationId"><option value="">Sin sucursal asignada</option>${locations.map(l=>`<option value="${attr(l.id)}">${esc(l.name)}</option>`).join('')}</select></label><label class="full">Descripción<textarea name="description" maxlength="1000" placeholder="Describe la experiencia"></textarea></label></div><div class="form-actions"><button class="btn btn-primary" type="submit">Publicar evento ↗</button></div></form></section><section><h2 style="margin-bottom:15px">Eventos publicados (${events.length})</h2><div class="grid three">${events.length?events.map(ev=>eventCard(ev,true)).join(''):empty('Todavía no has publicado ningún evento.')}</div></section>`;}
function companyReservationsPage(){const r=app.data.reservations;return `${page('CONTROL DE ASISTENCIA','Reservaciones','Revisa quién reservó, cuándo lo hizo y confirma la asistencia.',`${badge(r.length+' registros')}`)}<section class="panel"><div class="panel-head"><h3>Historial y estados</h3>${badge('Tiempo real al actualizar','green')}</div>${r.length?`<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Evento y lugar</th><th>Fecha del evento</th><th>Reservada el</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${r.map(x=>`<tr><td><strong>${esc(x.customer_name)}</strong><br><small>${esc(x.customer_email)}</small></td><td>${esc(x.title)}<br><small>${esc(x.location_name||'Sin sucursal')}</small></td><td>${fmtDate(x.date)} · ${esc(x.time)}</td><td>${fmtStamp(x.created_at)}</td><td>${statusTag(x.status)}</td><td>${x.status==='confirmed'?`<div class="gap8"><button class="btn btn-sm btn-soft" data-action="attend-res" data-id="${attr(x.id)}">Asistió</button><button class="btn btn-sm btn-danger" data-action="no-show-res" data-id="${attr(x.id)}">No asistió</button></div>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay reservas. Publica un evento y comparte la plataforma con clientes.')}</section>`;}
function rewardsPage(){const {rewards,redemptions}=app.data;return `${page('CLUB DE BENEFICIOS','Recompensas','Premia a tus clientes con puntos que se descuentan al canjear.') }<div class="grid two"><section class="panel"><div class="panel-head"><h3>Crear recompensa</h3>${badge('Saldo verificado','green')}</div><form class="vstack" data-form="reward"><label>Nombre<input name="name" required maxlength="100" placeholder="Bebida de cortesía"></label><div class="fields"><label>Costo en puntos<input name="cost" type="number" min="1" max="1000000" value="100" required></label><label>Existencias (vacío = ilimitado)<input name="stock" type="number" min="0" max="100000" placeholder="Sin límite"></label></div><label>Descripción<textarea name="description" maxlength="400" placeholder="Condiciones del beneficio"></textarea></label><button class="btn btn-primary" type="submit">Crear recompensa</button></form></section><section class="panel"><div class="panel-head"><h3>Catálogo activo</h3>${badge(rewards.length+' recompensas')}</div>${rewards.length?`<div class="mini-list">${rewards.map(r=>`<div class="item"><div><strong>${esc(r.name)}</strong><p>${esc(r.description||'Sin descripción')} · ${r.stock===null?'Ilimitada':r.stock+' disponibles'}</p></div>${badge(r.cost+' pts','gold')}</div>`).join('')}</div>`:empty('No hay recompensas. Crea la primera.')}</section></div><section class="panel"><div class="panel-head"><h3>Historial de canjes</h3>${badge(`${redemptions.length} canjes`)}</div>${redemptions.length?`<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Recompensa</th><th>Puntos descontados</th><th>Fecha</th></tr></thead><tbody>${redemptions.map(r=>`<tr><td>${esc(r.customer)}<br><small>${esc(r.email)}</small></td><td>${esc(r.reward)}</td><td>-${r.cost} pts</td><td>${fmtStamp(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Los canjes aparecerán aquí.')}</section>`;}
function campaignsPage(){const cs=app.data.campaigns;return `${page('COMUNICACIÓN INTELIGENTE','Campañas','Diseña mensajes y guárdalos como borradores. El envío todavía no está activado.') }<div class="grid two"><section class="panel"><div class="panel-head"><h3>Nueva campaña</h3>${badge('Borrador','gold')}</div><form class="vstack" data-form="campaign"><label>Título<input name="title" maxlength="100" required placeholder="Vuelve por tu favorito"></label><div class="fields"><label>Audiencia<select name="audience"><option>Todos</option><option>Clientes nuevos</option><option>Clientes inactivos</option><option>Clientes recurrentes</option></select></label><label>Canal previsto<select name="channel"><option>Correo</option><option>WhatsApp</option><option>Notificación</option></select></label></div><label>Mensaje<textarea name="message" required maxlength="2000" placeholder="Hola, tenemos algo especial para ti..."></textarea></label><button type="submit" class="btn btn-primary">Guardar borrador</button><p class="help">No se enviarán mensajes sin proveedor configurado, consentimiento y confirmación.</p></form></section><section class="panel"><div class="panel-head"><h3>Campañas guardadas</h3>${badge(cs.length+' borradores')}</div>${cs.length?`<div class="mini-list">${cs.map(c=>`<div class="item"><div><strong>${esc(c.title)}</strong><p>${esc(c.message)}</p><p>${esc(c.audience)} · ${esc(c.channel)}</p></div>${statusTag(c.status)}</div>`).join('')}</div>`:empty('Aquí aparecerán tus campañas.')}</section></div>`;}
function insightsPage(){const a=app.data.insights;return `${page('CENTRO DE ANÁLISIS','Tu asistente de negocio ✨','Conclusiones generadas directamente desde operaciones registradas.') }<div class="panel panel-dark hero" style="min-height:220px"><div><div class="eyebrow">RECOMENDACIONES BASADAS EN DATOS</div><h2>Información que puedes verificar.</h2><p>Este asistente local consulta tu base de datos. No inventa resultados ni envía datos a un proveedor externo de IA.</p></div></div><div class="grid two"><section class="panel"><div class="panel-head"><h3>Observaciones del negocio</h3>${badge(a.provider,'green')}</div><div class="mini-list">${a.insights.map((x,i)=>`<div class="item"><span style="font-size:1.3rem;color:#c59b3c">✧</span><div style="flex:1">${esc(x)}</div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>Siguiente acción sugerida</h3></div><div class="recommendation"><strong>Una oportunidad para crecer</strong><p>${esc(a.recommendation)}</p></div>${a.aiEnabled?`<div class="divider"></div><h3>Preguntar a la IA</h3><form data-form="ask-ai" class="vstack" style="margin-top:12px"><label>Tu pregunta<textarea name="question" maxlength="450" required placeholder="¿Qué estrategia me recomiendas para aumentar las visitas?"></textarea></label><label style="display:flex;align-items:flex-start;gap:8px;flex-direction:row"><input type="checkbox" name="allowExternal" value="yes" required style="width:auto;min-height:auto;margin-top:4px"><span>Autorizo enviar mi pregunta y métricas agregadas (sin correos ni datos individuales) a un proveedor de IA externo.</span></label><button class="btn btn-primary">Preguntar a Centro I.A. ✨</button></form>${app.aiAnswer?`<div class="recommendation" style="margin-top:16px"><strong>Respuesta de IA</strong><p>${esc(app.aiAnswer)}</p></div>`:''}`:`<p class="help" style="margin-top:16px">La IA generativa permanece desactivada hasta configurar OPENAI_API_KEY en el servidor. Estos resultados son análisis por reglas, no IA generativa.</p>`}<button class="btn btn-soft" data-nav="campaigns" style="margin-top:18px">Preparar campaña →</button></section></div>`;}
function teamPage(){const team=app.data.team;const role=app.businesses.find(b=>b.id===app.businessId)?.role;return `${page('COLABORACIÓN SEGURA','Equipo y permisos','Agrega administradores o empleados con un código de invitación limitado.') }<div class="grid two"><section class="panel"><div class="panel-head"><h3>Integrantes</h3>${badge(team.length+' personas')}</div><div class="mini-list">${team.map(p=>`<div class="item"><div><strong>${esc(p.name)}</strong><p>${esc(p.email)}</p></div>${badge(p.role==='owner'?'Propietario':p.role==='admin'?'Administrador':'Empleado')}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>Invitar integrante</h3></div>${role==='owner'?`<form data-form="invite" class="vstack"><label>Correo de la persona<input type="email" name="email" required></label><label>Rol<select name="role"><option value="staff">Empleado</option><option value="admin">Administrador</option></select></label><button class="btn btn-primary" type="submit">Generar invitación</button><small>El invitado debe registrarse con cuenta Empresa. Recibirá un código que podrás compartir en privado.</small></form>`:empty('Solo el propietario puede invitar personal.')}<div id="invite-output" class="help" style="margin-top:12px"></div></section></div><div class="panel"><h3>¿Tienes un código de invitación?</h3><form data-form="accept-invite" class="actions" style="margin-top:12px"><label style="min-width:240px;flex:1">Código recibido<input name="code" required placeholder="Pega tu código aquí"></label><button class="btn btn-soft" type="submit">Unirme a un equipo</button></form></div>`;}
function settingsPage(){const b=app.data.business,loc=app.data.locations;const canEdit=['owner','admin'].includes(app.businesses.find(x=>x.id===app.businessId)?.role);return `${page('IDENTIDAD Y SUCURSALES','Configuración del negocio','Controla los datos públicos de tu establecimiento y dónde atiendes.') }<div class="grid two"><section class="panel"><div class="panel-head"><h3>Datos del negocio</h3>${badge('Público')}</div><form data-form="edit-business" class="vstack"><label>Nombre<input name="name" value="${attr(b.name)}" required maxlength="100" ${canEdit?'':'disabled'}></label><label>Categoría<input name="category" value="${attr(b.category)}" maxlength="60" ${canEdit?'':'disabled'}></label><label>Ciudad<input name="city" value="${attr(b.city)}" maxlength="80" ${canEdit?'':'disabled'}></label><label>Dirección<input name="address" value="${attr(b.address)}" maxlength="180" ${canEdit?'':'disabled'}></label><label>Teléfono<input name="phone" value="${attr(b.phone||'')}" maxlength="35" ${canEdit?'':'disabled'}></label><label>Descripción<textarea name="description" maxlength="500" ${canEdit?'':'disabled'}>${esc(b.description)}</textarea></label>${canEdit?'<button class="btn btn-primary" type="submit">Guardar cambios</button>':''}</form></section><section class="vstack"><div class="panel"><div class="panel-head"><h3>Sucursales</h3>${badge(loc.length+' registradas')}</div><div class="mini-list">${loc.map(l=>`<div class="item"><div><strong>${esc(l.name)}</strong><p>${esc(l.address||'Sin dirección')} ${esc(l.city||'')}</p></div></div>`).join('')}</div></div>${canEdit?`<div class="panel"><h3>Agregar sucursal</h3><form data-form="location" class="vstack" style="margin-top:15px"><label>Nombre<input name="name" required maxlength="80" placeholder="Sucursal centro"></label><label>Dirección<input name="address" maxlength="180"></label><label>Ciudad<input name="city" maxlength="80"></label><label>Horario habitual<input name="hours" maxlength="90" placeholder="9:00 a 21:00"></label><button class="btn btn-primary" type="submit">Agregar sucursal</button></form></div>`:''}</section></div>`;}
function auditPage(){const log=app.data.audit;return `${page('TRAZABILIDAD','Historial de operaciones','Registro de movimientos de la empresa y sus responsables.') }<section class="panel">${log.length?`<div class="table-wrap"><table><thead><tr><th>Acción</th><th>Detalle</th><th>Responsable</th><th>Fecha</th></tr></thead><tbody>${log.map(x=>`<tr><td><strong>${esc(x.action)}</strong></td><td>${esc(x.detail)}</td><td>${esc(x.actor)}</td><td>${fmtStamp(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay movimientos.')}</section>`;}
function discoverPage(){const bs=app.data.businesses;return `${page('TU COMUNIDAD EN CENTRO I.A.','¡Hola, '+app.user.name.split(' ')[0]+'! ✨','Descubre negocios que realmente han creado una cuenta en la plataforma.') }<section class="panel panel-dark hero"><div><div class="eyebrow">EXPERIENCIAS Y BENEFICIOS</div><h2>Volver a tus lugares favoritos tiene más sentido.</h2><p>Consulta eventos disponibles, reserva un lugar y acumula puntos cuando el negocio confirme tus visitas.</p></div><div class="hero-bottom">${badge('Tu cuenta está sincronizada','green')}<button class="btn btn-primary" data-nav="events">Explorar eventos →</button></div></section><section><h2 style="margin-bottom:17px">Negocios disponibles (${bs.length})</h2><div class="grid three">${bs.length?bs.map(b=>`<article class="card"><div class="gap8">${badge(b.category,'gold')}${badge(`${b.events} eventos`)}</div><h3>${esc(b.name)}</h3><p>${esc(b.description||'Un nuevo negocio en Centro I.A.')}</p><p>⌖ ${esc(b.city||'Ubicación por confirmar')}</p><div class="card-footer"><button class="btn btn-soft btn-sm" data-action="follow" data-id="${attr(b.id)}">♡ Seguir club</button><button class="btn btn-primary btn-sm" data-nav="events">Ver eventos →</button></div></article>`).join(''):empty('Todavía no hay negocios registrados. Comparte la plataforma con una empresa para comenzar.')}</div></section>`;}
function userEventsPage(){const {events,reservations}=app.data,ids=new Set(reservations.filter(x=>['confirmed','attended','no_show'].includes(x.status)).map(x=>x.event_id));const upcoming=events.filter(x=>x.date>=new Date().toLocaleDateString('en-CA'));
return `${page('CALENDARIO DE EXPERIENCIAS','Explora y reserva','Las reservas se confirman en el servidor y se controla el cupo del evento.') }<div class="grid three">${upcoming.length?upcoming.map(x=>eventCard(x,false,ids.has(x.id))).join(''):empty('No hay próximos eventos publicados.')}</div><div class="recommendation"><strong>Reserva real, sin cobrar por adelantado</strong><p>La reserva aparta un cupo, pero no procesa pagos. Los eventos de pago requieren confirmación externa antes de un lanzamiento comercial.</p></div>`;}
function userReservationsPage(){const r=app.data.reservations;return `${page('TUS PLANES','Mis reservaciones','Consulta dónde y cuándo reservaste, el estado y las últimas operaciones.',badge(r.length+' registradas'))}<section class="panel"><div class="panel-head"><h3>Historial de reservas</h3>${badge('Vinculado a tu cuenta','green')}</div>${r.length?`<div class="table-wrap"><table><thead><tr><th>Negocio</th><th>Evento</th><th>Fecha y hora</th><th>Fecha de reserva</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${r.map(x=>`<tr><td>${esc(x.business_name)}</td><td><strong>${esc(x.title)}</strong><br><small>${esc(x.location_name||'Lugar por confirmar')}</small></td><td>${fmtDate(x.date)} · ${esc(x.time)}</td><td>${fmtStamp(x.created_at)}</td><td>${statusTag(x.status)}</td><td>${x.status==='confirmed'?`<button class="btn btn-danger btn-sm" data-action="cancel-res" data-id="${attr(x.id)}">Cancelar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Aún no tienes reservas. Explora los eventos disponibles.',`<button class="btn btn-primary" data-nav="events">Encontrar eventos</button>`)}</section>`;}
function walletPage(){const {wallet,ledger}=app.data;return `${page('TU CLUB DE BENEFICIOS','Mi billetera','Cada negocio lleva sus puntos de forma independiente; todos los movimientos quedan registrados.') }<section class="panel panel-white"><div class="panel-head"><div><h3>Mi código QR de visita</h3><p>Muéstralo al personal del negocio cuando te visite.</p></div>${badge('Un solo uso · 5 min','gold')}</div><div class="actions"><button class="btn btn-primary" data-action="generate-qr">▣ Generar QR temporal</button>${app.visitCode?`<div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap"><img src="${attr(app.visitCode.qrImage)}" width="210" height="210" alt="QR de visita temporal" style="border:8px solid white;border-radius:12px"><div><div class="eyebrow">CÓDIGO MANUAL</div><strong style="font-size:1.15rem;overflow-wrap:anywhere">${esc(app.visitCode.code)}</strong><p class="help">Vence: ${esc(new Date(app.visitCode.expiresAt).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}))}. No lo compartas públicamente.</p></div></div>`:''}</div></section><div class="grid three">${wallet.length?wallet.map(w=>`<article class="card"><div class="gap8">${badge('Miembro activo','green')}</div><h3>${esc(w.business_name)}</h3><div style="font-size:2.25rem;font-weight:850;letter-spacing:-.04em">${w.points} <small>pts</small></div><p>${w.visits} visitas registradas · Última: ${fmtDate(w.last_visit_at)}</p><div class="divider"></div><h3>Canjear recompensas</h3>${w.rewards.length?`<div class="mini-list">${w.rewards.map(r=>`<div class="item"><div><strong>${esc(r.name)}</strong><p>${r.cost} pts · ${r.stock===null?'Sin límite':r.stock+' disponibles'}</p></div><button class="btn btn-sm ${w.points>=r.cost?'btn-primary':'btn-soft'}" data-action="redeem" data-id="${attr(r.id)}" ${w.points<r.cost||r.stock===0?'disabled':''}>Canjear</button></div>`).join('')}</div>`:empty('Este negocio todavía no tiene recompensas.')}</article>`).join(''):empty('Todavía no tienes puntos. Visita un negocio registrado y pide que confirme tu visita.')}</div><section class="panel"><div class="panel-head"><h3>Movimientos de puntos</h3>${badge(ledger.length+' movimientos')}</div>${ledger.length?`<div class="table-wrap"><table><thead><tr><th>Negocio</th><th>Movimiento</th><th>Puntos</th><th>Fecha</th></tr></thead><tbody>${ledger.map(x=>`<tr><td>${esc(x.business_name)}</td><td>${esc(x.reason)}</td><td>${x.delta>0?'+':''}${x.delta}</td><td>${fmtStamp(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No hay movimientos todavía.')}</section>`;}
function notificationsPage(){const ns=app.data.notifications;return `${page('LO QUE ESTÁ PASANDO','Notificaciones','Avisos creados por acciones reales de la plataforma.',`<button class="btn btn-soft" data-action="mark-read">Marcar todas como leídas</button>`)}<section class="panel">${ns.length?ns.map(n=>`<div class="alert-item"><div class="gap8">${n.read?'':badge('Nuevo','gold')}<strong>${esc(n.title)}</strong></div><p>${esc(n.detail)}</p><small>${fmtStamp(n.created_at)}</small></div>`).join(''):empty('Aún no tienes notificaciones.')}</section>`;}
function profilePage(){return `${page('TU CUENTA','Mi perfil','Administra los datos de tu cuenta y descarga tus registros.') }<div class="grid two"><section class="panel"><div class="panel-head"><h3>Información personal</h3>${badge(app.user.accountType==='company'?'Cuenta Empresa':'Cuenta Usuario')}</div><form class="vstack" data-form="profile"><label>Nombre<input name="name" maxlength="90" required value="${attr(app.user.name)}"></label><label>Correo electrónico<input value="${attr(app.user.email)}" disabled></label><small>El correo no se cambia desde esta versión.</small><button type="submit" class="btn btn-primary">Guardar nombre</button></form></section><section class="panel"><div class="panel-head"><h3>Tus datos</h3></div><p>Consulta los registros asociados con esta cuenta y descarga una copia en JSON para respaldo personal.</p><button class="btn btn-soft" data-action="export-personal" style="margin-top:18px">Descargar mis datos ↧</button><p class="help" style="margin-top:18px">La eliminación de cuentas, verificación de correo y recuperación de contraseñas deben completarse antes de abrir el servicio al público.</p><div class="divider"></div><h3>Cambiar contraseña</h3><form class="vstack" data-form="change-password" style="margin-top:12px"><label>Contraseña actual<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>Contraseña nueva (mínimo 10 caracteres)<input name="newPassword" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><button class="btn btn-soft" type="submit">Cambiar contraseña</button></form>${app.user.accountType==='company'?`<div class="divider"></div><h3>Unirse al equipo de un negocio</h3><form class="vstack" data-form="accept-invite" style="margin-top:10px"><label>Código de invitación<input name="code" required></label><button class="btn btn-soft" type="submit">Aceptar invitación</button></form>`:''}</section></div>`;}
async function operation(fn,ok){if(app.busy)return;app.busy=true;try{await fn();if(ok)toast(ok);await refresh();}catch(e){toast(e.message,true);}finally{app.busy=false;}}
const formData=form=>Object.fromEntries(new FormData(form).entries());
function generateIdempotency(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;}
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(app.busy)return;const data=formData(f);const kind=f.dataset.form;await operation(async()=>{
  if(kind==='register'||kind==='login'){
    const result=await api('/api/auth/'+kind,{method:'POST',body:data});app.user=result.user;app.businesses=result.businesses||[];app.csrf=result.csrf;app.businessId=app.businesses[0]?.id||null;app.visitCode=null;app.aiAnswer='';app.mode=app.user.accountType==='company'?'business':'user';app.view=app.mode==='business'?'dashboard':'discover';return;
  }
  if(kind==='create-business'){await api('/api/businesses',{method:'POST',body:data});const next=await api('/api/bootstrap');app.businesses=next.businesses;app.businessId=app.businesses[0]?.id;app.mode='business';app.view='dashboard';app.creatingBusiness=false;return;}
  if(kind==='checkin'){await api(`/api/businesses/${bid()}/checkin`,{method:'POST',body:{...data,points:Number(data.points)}});return;}
  if(kind==='visit'){await api(`/api/businesses/${bid()}/visits`,{method:'POST',body:{...data,points:Number(data.points),idempotencyKey:f.dataset.idempotencyKey||(f.dataset.idempotencyKey=generateIdempotency())}});delete f.dataset.idempotencyKey;return;}
  if(kind==='event'){await api(`/api/businesses/${bid()}/events`,{method:'POST',body:{...data,capacity:Number(data.capacity),priceCents:Math.round(Number(data.price)*100)}});return;}
  if(kind==='reward'){await api(`/api/businesses/${bid()}/rewards`,{method:'POST',body:{...data,cost:Number(data.cost),stock:data.stock===''?null:Number(data.stock)}});return;}
  if(kind==='campaign'){await api(`/api/businesses/${bid()}/campaigns`,{method:'POST',body:data});return;}
  if(kind==='edit-business'){await api(`/api/businesses/${bid()}`,{method:'PATCH',body:data});const next=await api('/api/bootstrap');app.businesses=next.businesses;return;}
  if(kind==='location'){await api(`/api/businesses/${bid()}/locations`,{method:'POST',body:data});return;}
  if(kind==='invite'){const out=await api(`/api/businesses/${bid()}/invites`,{method:'POST',body:data});await navigator.clipboard?.writeText(out.inviteCode).catch(()=>{});alert(`Código de invitación (7 días):\n${out.inviteCode}\n\nCópialo y compártelo de forma privada con ${data.email}.`);return;}
  if(kind==='accept-invite'){await api('/api/invites/accept',{method:'POST',body:data});const next=await api('/api/bootstrap');app.businesses=next.businesses;app.businessId=app.businesses[0]?.id;app.mode='business';app.creatingBusiness=false;app.view='dashboard';return;}
  if(kind==='profile'){await api('/api/me',{method:'PATCH',body:data});app.user.name=data.name;return;}
  if(kind==='change-password'){await api('/api/me/password',{method:'POST',body:data});return;}
  if(kind==='ask-ai'){const response=await api(`/api/businesses/${bid()}/ai/ask`,{method:'POST',body:{question:data.question,allowExternal:data.allowExternal==='yes'}});app.aiAnswer=response.answer;return;}
},kind==='register'||kind==='login'?'Sesión iniciada':kind==='visit'?'Visita registrada y puntos actualizados.':kind==='accept-invite'?'Invitación aceptada.':'Cambios guardados en el servidor.');});
document.addEventListener('click',async e=>{
  const n=e.target.closest('[data-nav]');if(n){await go(n.dataset.nav);return;}
  const days=e.target.closest('[data-days]');if(days){app.days=Number(days.dataset.days);await refresh();return;}
  const b=e.target.closest('[data-action]');if(!b)return;
  const action=b.dataset.action,id=b.dataset.id;
  if(action==='retry'){await boot();return;}
  if(action==='auth-toggle'){app.authView=app.authView==='login'?'register':'login';render();return;}
  if(action==='logout'){await operation(async()=>{await api('/api/auth/logout',{method:'POST',body:{}});app.user=null;app.businessId=null;app.businesses=[];app.csrf='';app.visitCode=null;app.aiAnswer='';app.creatingBusiness=false;app.data={};app.view='discover';app.mode='user';app.authView='login';},'Sesión cerrada.');return;}
  if(action==='new-business'){app.creatingBusiness=true;render();return;}
  if(action==='cancel-new-business'){app.creatingBusiness=false;render();return;}
  if(action==='switch-mode'){app.mode=app.mode==='business'?'user':'business';app.view=app.mode==='business'?'dashboard':'discover';await refresh();return;}
  if(action==='generate-qr'){await operation(async()=>{app.visitCode=await api('/api/me/visit-code',{method:'POST',body:{}});},'Nuevo código QR disponible.');return;}
  if(action==='scan-qr'){await startScanner();return;}
  if(action==='book-event'){if(!confirm('¿Confirmar tu lugar para este evento?'))return;await operation(()=>api(`/api/events/${encodeURIComponent(id)}/reservations`,{method:'POST',body:{}}),'Reservación confirmada.');return;}
  if(action==='cancel-event'){if(!confirm('¿Cancelar este evento y las reservas confirmadas?'))return;await operation(()=>api(`/api/events/${encodeURIComponent(id)}`,{method:'PATCH',body:{status:'cancelled'}}),'Evento cancelado.');return;}
  if(action==='cancel-res'){if(!confirm('¿Cancelar esta reservación?'))return;await operation(()=>api(`/api/reservations/${encodeURIComponent(id)}`,{method:'PATCH',body:{status:'cancelled'}}),'Reserva cancelada.');return;}
  if(action==='attend-res'||action==='no-show-res'){await operation(()=>api(`/api/reservations/${encodeURIComponent(id)}`,{method:'PATCH',body:{status:action==='attend-res'?'attended':'no_show'}}),'Asistencia actualizada.');return;}
  if(action==='redeem'){if(!confirm('¿Canjear esta recompensa? Se descontarán puntos de tu cuenta.'))return;await operation(()=>api(`/api/rewards/${encodeURIComponent(id)}/redeem`,{method:'POST',body:{}}),'¡Recompensa canjeada!');return;}
  if(action==='follow'){await operation(()=>api(`/api/businesses/${encodeURIComponent(id)}/follow`,{method:'POST',body:{}}),'Negocio añadido a tus favoritos.');return;}
  if(action==='mark-read'){await operation(()=>api('/api/me/notifications/read',{method:'PATCH',body:{}}),'Notificaciones leídas.');return;}
  if(action==='export-personal'){try{const data=await api('/api/me/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='centro-ia-mis-datos.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){toast(err.message,true);}return;}
});
async function startScanner(){
  if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('La cámara QR no está disponible aquí. Escribe el código manualmente.',true);return;}
  const dialog=document.createElement('dialog');dialog.style.cssText='border:1px solid #d2e3ef;border-radius:20px;padding:20px;max-width:min(420px,95vw);box-shadow:0 25px 75px #1a34547a';
  dialog.innerHTML='<div class="vstack"><h3>Escanea el QR de visita</h3><video autoplay playsinline muted style="width:100%;border-radius:15px;background:#22354b"></video><small>Dirige la cámara al QR del cliente.</small><button class="btn btn-soft" data-close-camera>Cancelar escaneo</button></div>';
  document.body.appendChild(dialog);dialog.showModal();let stopped=false,stream=null;
  const stop=()=>{stopped=true;stream?.getTracks().forEach(t=>t.stop());dialog.close();dialog.remove();};
  dialog.querySelector('[data-close-camera]').addEventListener('click',stop);
  dialog.addEventListener('cancel',e=>{e.preventDefault();stop();});
  try{
    stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});
    const video=dialog.querySelector('video');video.srcObject=stream;await video.play();
    const detector=new BarcodeDetector({formats:['qr_code']});
    const loop=async()=>{
      if(stopped)return;
      try{const codes=await detector.detect(video);const raw=codes[0]?.rawValue?.trim().toUpperCase();if(raw&&/^CIA-[A-HJ-NP-Z2-9]{16}$/.test(raw)){
        const input=$('#qr-code-input');if(input)input.value=raw;stop();toast('QR leído. Confirma los puntos para registrar la visita.');return;
      }}catch{}
      if(!stopped)requestAnimationFrame(loop);
    };requestAnimationFrame(loop);
  }catch(e){stop();toast('No se pudo abrir la cámara. Usa el código manual.',true);}
}
document.addEventListener('change',async e=>{if(e.target.id==='business-select'){app.businessId=e.target.value;await go('dashboard');}});
boot();
// Disponible en HTTPS o localhost; la app sigue requiriendo internet para los datos del servidor.
if('serviceWorker' in navigator&&window.isSecureContext){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));}